import{_ as e,c as t,o as l,Q as i}from"./chunks/framework.5f28ab71.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"compiler/构建compile/12-总结.md","lastUpdated":1724251318000}'),o={name:"compiler/构建compile/12-总结.md"},r=i('<h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>到这里我们就已经完成了一个基础的编辑器处理。</p><p>我们知道整个编辑器的处理过程分成了三部分：</p><ol><li><p><strong>解析模板 template 为 AST</strong></p><ul><li>在这一步过程中，我们使用了有限自动状态机解析模板得到了 tokens。</li><li>通过扫描 tokens 最终得到了 AST。</li></ul></li><li><p><strong>转化 AST 为 JavaScript AST</strong></p><ul><li>这一步是为了最终生成 render 函数做准备。</li><li>利用了深度优先的方式，进行了自下向上的逐层转化。</li></ul></li><li><p><strong>生成 render 函数</strong></p><ul><li>这一步是最后的解析环节，我们需要对 JavaScript AST 进行处理，得到最终的 render 函数。</li></ul></li></ol><p>整个一套编辑器的流程非常复杂，我们目前只完成了最基础的编辑逻辑，目前只能支持 <code>&lt;div&gt;文本&lt;/div&gt;</code> 的处理。那么如果我们想要处理更复杂的逻辑，比如：</p><ul><li>响应性数据</li><li>多个子节点</li><li>指令</li></ul><p>的话，对比编辑器而言，还需要做更多的事情才可以。</p>',7),a=[r];function p(n,s,_,c,d,u){return l(),t("div",null,a)}const T=e(o,[["render",p]]);export{S as __pageData,T as default};
